/* styles/native-elements.css */
/* =========================================================
   UI Style Kit CSS - Shared Native Element Layer

   Native fallback selectors are shared so UI presets can focus
   on visual identity while inheriting the same semantic coverage.
   Presets map --usk-native-* tokens to their public prefix tokens.
========================================================= */

@layer ui-style-kit.native_elements {
[data-ui][data-theme][data-mode] {
  --usk-native-surface: rgb(var(--usk-surface-rgb));
  --usk-native-surface-strong: rgb(var(--usk-surface-strong-rgb));
  --usk-native-surface-soft: rgb(var(--usk-surface-soft-rgb));
  --usk-native-card-bg: var(--usk-native-surface);
  --usk-native-control-bg: var(--usk-native-surface-soft);
  --usk-native-text: rgb(var(--usk-text-rgb));
  --usk-native-text-muted: rgb(var(--usk-text-muted-rgb));
  --usk-native-border: rgb(var(--usk-border-rgb));
  --usk-native-primary: rgb(var(--usk-primary-rgb));
  --usk-native-primary-hover: rgb(var(--usk-primary-hover-rgb));
  --usk-native-on-primary: rgb(var(--usk-primary-text-rgb));
  --usk-native-focus: rgb(var(--usk-focus-rgb));
  --usk-native-success: rgb(var(--usk-success-rgb));
  --usk-native-warning: rgb(var(--usk-warning-rgb));
  --usk-native-danger: rgb(var(--usk-danger-rgb));
  --usk-native-link: rgb(var(--usk-link-rgb));
  --usk-native-font-body: inherit;
  --usk-native-font-heading: inherit;
  --usk-native-font-control: inherit;
  --usk-native-font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  --usk-native-radius-sm: .5rem;
  --usk-native-radius: .75rem;
  --usk-native-radius-lg: 1rem;
  --usk-native-border-width: 1px;
  --usk-native-field-gap: .5rem;
  --usk-native-panel-padding: 1rem;
  --usk-native-control-min-block-size: 2.75rem;
  --usk-native-control-padding-block: .72rem;
  --usk-native-control-padding-inline: .95rem;
  --usk-native-subcontrol-padding-block: .55rem;
  --usk-native-subcontrol-padding-inline: .8rem;
  --usk-native-track: var(--usk-native-border);
  --usk-native-track-fill: var(--usk-native-primary);
  --usk-native-thumb: var(--usk-native-surface-strong);
  --usk-native-thumb-border: var(--usk-native-primary);
  --usk-native-indicator: var(--usk-native-primary);
  --usk-native-choice-size: 1.5rem;
  --usk-native-choice-background: var(--usk-native-control-bg);
  --usk-native-choice-border: var(--usk-native-border-width) solid var(--usk-native-border);
  --usk-native-checkbox-radius: .3rem;
  --usk-native-radio-radius: 50%;
  --usk-native-choice-shadow: none;
  --usk-native-choice-checked-background: var(--usk-native-primary);
  --usk-native-choice-mark-color: var(--usk-native-on-primary);
  --usk-native-select-indicator-image: linear-gradient(45deg, transparent 50%, var(--usk-native-indicator) 50%), linear-gradient(135deg, var(--usk-native-indicator) 50%, transparent 50%);
  --usk-native-select-indicator-size: .42rem .42rem, .42rem .42rem;
  --usk-native-select-indicator-position: calc(100% - 1.15rem) 50%, calc(100% - .85rem) 50%;
  --usk-native-select-padding-inline-end: 2.5rem;
  --usk-native-range-track-size: .45rem;
  --usk-native-range-track-background: var(--usk-native-track);
  --usk-native-range-track-border: 0 solid transparent;
  --usk-native-range-track-radius: 999px;
  --usk-native-range-track-shadow: none;
  --usk-native-range-progress-background: var(--usk-native-track-fill);
  --usk-native-range-thumb-size: 1.2rem;
  --usk-native-range-thumb-background: var(--usk-native-thumb);
  --usk-native-range-thumb-border: var(--usk-native-border-width) solid var(--usk-native-thumb-border);
  --usk-native-range-thumb-radius: 50%;
  --usk-native-range-thumb-shadow: var(--usk-native-shadow);
  --usk-native-progress-size: .9rem;
  --usk-native-progress-track-background: var(--usk-native-track);
  --usk-native-progress-track-border: 0 solid transparent;
  --usk-native-progress-track-radius: 999px;
  --usk-native-progress-track-shadow: none;
  --usk-native-progress-value-background: var(--usk-native-track-fill);
  --usk-native-progress-value-radius: inherit;
  --usk-native-progress-value-shadow: none;
  --usk-native-meter-optimum-background: var(--usk-native-success);
